script.setup:
// umap-learn embedded scikit-learn's 8x8 handwritten digits in 2D (recipe
// umap.digits-embedding → digits.json). Points fly into place; hover one to see the digit.
const data = await (await fetch(ctx.assets["digits.json"])).json();
const gl = ctx.gl, n = data.count;
const palette = ["#ff6b6b", "#ffa94d", "#ffd43b", "#a9e34b", "#38d9a9", "#3bc9db", "#4dabf7", "#9775fa", "#da77f2", "#f783ac"]
  .map((h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255));
const inst = new Float32Array(n * 6);
for (let i = 0; i < n; i++) {
  const c = palette[data.labels[i]];
  // Start each point on a ring, ordered by label, so the intro unfolds the clusters.
  const a = (data.labels[i] + Math.random() * 0.9) / 10 * Math.PI * 2;
  inst.set([data.points[i * 2], data.points[i * 2 + 1], Math.cos(a) * 1.25, Math.sin(a) * 1.25, data.labels[i], i], i * 6);
}
const vao = gl.createVertexArray();
gl.bindVertexArray(vao);
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, inst, gl.STATIC_DRAW);
for (const [loc, size, off] of [[1, 2, 0], [2, 2, 2], [3, 1, 4], [4, 1, 5]]) {
  gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 24, off * 4); gl.vertexAttribDivisor(loc, 1);
}
gl.bindVertexArray(null);
const vs = `#version 300 es
layout(location=0) in vec2 a_corner; layout(location=1) in vec2 a_pos; layout(location=2) in vec2 a_start; layout(location=3) in float a_label; layout(location=4) in float a_index;
uniform vec2 u_resolution; uniform float u_intro; uniform float u_size; uniform float u_focus; uniform float u_hoverIndex; uniform vec3 u_palette[10]; uniform float u_time;
out vec2 v_q; out vec3 v_color; out float v_alpha;
void main(){
  float delay = fract(sin(a_index * 12.9898) * 43758.5453) * 0.35;
  float t = clamp((u_intro - delay) / 0.65, 0.0, 1.0); t = t * t * (3.0 - 2.0 * t);
  vec2 p = mix(a_start, a_pos, t);
  p += 0.006 * vec2(sin(u_time * 0.7 + a_index), cos(u_time * 0.6 + a_index * 1.3)) * t;
  bool lit = u_focus < 0.0 || abs(a_label - u_focus) < 0.5;
  bool hot = abs(a_index - u_hoverIndex) < 0.5;
  float size = u_size * (hot ? 3.2 : lit ? 1.0 : 0.7);
  float m = min(u_resolution.x, u_resolution.y) * 0.42;
  vec2 px = p * m + a_corner * size;
  v_q = a_corner; v_color = hot ? vec3(1.0) : u_palette[int(a_label)]; v_alpha = lit ? 1.0 : 0.16;
  gl_Position = vec4(px / (u_resolution * 0.5), 0.0, 1.0);
}`;
const fs = `#version 300 es
precision highp float; in vec2 v_q; in vec3 v_color; in float v_alpha; out vec4 outColor;
void main(){ float d = dot(v_q, v_q); if (d > 1.0) discard;
  float core = smoothstep(1.0, 0.55, d), glow = exp(-d * 3.0) * 0.6;
  float a = (core * 0.9 + glow * 0.4) * v_alpha; outColor = vec4(v_color * a, a); }`;
const overlay = new OffscreenCanvas(1, 1);
Object.assign(ctx.state, {
  data, vao, n, palette, overlay, o2d: overlay.getContext("2d"), tex: gl.createTexture(), key: "", hover: -1, start: ctx.time,
  // Median per axis, so a few strays don't pull a label away from its cluster.
  centroids: palette.map((_, d) => [0, 1].map((axis) => {
    const v = []; for (let i = 0; i < n; i++) if (data.labels[i] === d) v.push(data.points[i * 2 + axis]);
    return v.sort((a, b) => a - b)[v.length >> 1];
  })),
  p: ctx.utils.createProgram(vs, fs),
  over: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_tex;
void main(){ outColor = texture(u_tex, vec2(v_uv.x, 1.0 - v_uv.y)); }`),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
void main(){ vec2 q = v_uv - 0.5; outColor = vec4(mix(vec3(0.06, 0.06, 0.085), vec3(0.015, 0.015, 0.025), length(q) * 1.5), 1.0); }`),
});
ctx.publish("digits", n);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution, m = Math.min(w, h) * 0.42;
const intro = Math.min((ctx.time - s.start) / 3.5, 1);
// Nearest point to the mouse, in pixels.
const mx = (ctx.mouse[0] - 0.5) * w, my = (0.5 - ctx.mouse[1]) * h;
let best = -1, bestD = (u.u_size * 4) ** 2;
if (intro >= 1) for (let i = 0; i < s.n; i++) {
  const d = (s.data.points[i * 2] * m - mx) ** 2 + (s.data.points[i * 2 + 1] * m - my) ** 2;
  if (d < bestD) { bestD = d; best = i; }
}
s.hover = best;
const focus = best >= 0 ? s.data.labels[best] : -1;
ctx.publish("hover digit", focus >= 0 ? String(focus) : "");

ctx.utils.drawFullscreen(s.bg);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
gl.useProgram(s.p);
ctx.utils.setStandardUniforms(s.p);
ctx.utils.setUniforms(s.p, { u_intro: intro, u_focus: focus, u_hoverIndex: best, u_size: u.u_size * h / 720, u_palette: new Float32Array(s.palette.flat()) });
gl.bindVertexArray(s.vao);
gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, s.n);
gl.bindVertexArray(null);

// Overlay: class labels at cluster centers and the hovered 8x8 digit, redrawn when they change.
const key = `${w}x${h}:${best}:${intro >= 1}`;
if (key !== s.key) {
  s.key = key;
  const L = s.o2d;
  if (s.overlay.width !== w || s.overlay.height !== h) { s.overlay.width = w; s.overlay.height = h; }
  L.clearRect(0, 0, w, h);
  if (intro >= 1) {
    L.textAlign = "center"; L.textBaseline = "middle";
    const fsz = Math.round(h / 22);
    L.font = `700 ${fsz}px ui-sans-serif, system-ui, sans-serif`;
    s.centroids.forEach(([x, y], d) => {
      // Label on its cluster's median point, outlined so it reads over the dots.
      L.globalAlpha = focus < 0 || focus === d ? 1 : 0.3;
      L.lineWidth = fsz * 0.22; L.strokeStyle = "rgba(6,6,12,0.9)";
      L.strokeText(String(d), w / 2 + x * m, h / 2 - y * m);
      L.fillStyle = "white";
      L.fillText(String(d), w / 2 + x * m, h / 2 - y * m);
    });
    L.globalAlpha = 1;
  }
  if (best >= 0) {
    const cell = Math.round(h / 60), size = cell * 8, pad = cell, x0 = w - size - pad * 3, y0 = pad * 2;
    L.fillStyle = "rgba(8,8,14,0.85)"; L.beginPath(); L.roundRect(x0 - pad, y0 - pad, size + pad * 2, size + pad * 4.2, pad); L.fill();
    const col = s.palette[s.data.labels[best]];
    for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) {
      const v = s.data.pixels[best * 64 + r * 8 + c] / 16;
      L.fillStyle = `rgb(${col.map((k) => Math.round((0.08 + v * k * 0.92) * 255)).join(",")})`;
      L.fillRect(x0 + c * cell, y0 + r * cell, cell - 1, cell - 1);
    }
    L.fillStyle = "white"; L.textAlign = "center"; L.textBaseline = "middle"; L.font = `600 ${Math.round(cell * 1.3)}px ui-sans-serif, system-ui, sans-serif`;
    L.fillText(`#${best} · label ${s.data.labels[best]}`, x0 + size / 2, y0 + size + pad * 1.6);
  }
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.overlay);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
}
gl.useProgram(s.over);
ctx.utils.bindTexture(s.over, "u_tex", s.tex, 0);
ctx.utils.drawFullscreen(s.over);
gl.disable(gl.BLEND);
